-- Movie Nights production snapshot
-- generated 2026-09-22T07:07:34.752Z
--
-- Restore into a local SQLite file with:  sqlite3 movies.db < this-file.sql
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;

DROP TABLE IF EXISTS movies;
CREATE TABLE movies (
    id        INTEGER PRIMARY KEY AUTOINCREMENT,
    director  TEXT    NOT NULL DEFAULT '',
    title     TEXT    NOT NULL,
    year      TEXT    DEFAULT '',
    rank_global INTEGER,
    mn        INTEGER NOT NULL DEFAULT 0,
    watchlist INTEGER NOT NULL DEFAULT 0,
    cinobo    TEXT    DEFAULT '',
    tokens    TEXT    DEFAULT '',
    token_pts INTEGER NOT NULL DEFAULT 0
  , imdb_id TEXT DEFAULT NULL, imdb_rating REAL DEFAULT NULL, poster_path TEXT DEFAULT NULL, runtime INTEGER DEFAULT NULL, letterboxd_rating REAL DEFAULT NULL, backdrop_path TEXT DEFAULT NULL, stream_gr TEXT DEFAULT NULL, letterboxd_updated_at TEXT DEFAULT NULL);

DROP TABLE IF EXISTS ratings;
CREATE TABLE ratings (
    id       INTEGER PRIMARY KEY AUTOINCREMENT,
    movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    voter    TEXT    NOT NULL,
    score    REAL    NOT NULL, comment TEXT NOT NULL DEFAULT '', user_id INTEGER REFERENCES users(id),
    UNIQUE(movie_id, voter)
  );

DROP TABLE IF EXISTS top3;
CREATE TABLE "top3" (
        id       INTEGER PRIMARY KEY AUTOINCREMENT,
        movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
        voter    TEXT    NOT NULL,
        rank     INTEGER NOT NULL CHECK(rank >= 1 AND rank <= 10), user_id INTEGER REFERENCES users(id),
        UNIQUE(movie_id, voter)
      );

DROP TABLE IF EXISTS watchlist_votes;
CREATE TABLE watchlist_votes (
    id       INTEGER PRIMARY KEY,
    movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
    voter    TEXT    NOT NULL,
    UNIQUE(movie_id, voter)
  );

DROP TABLE IF EXISTS lists;
CREATE TABLE lists (
      id          INTEGER PRIMARY KEY AUTOINCREMENT,
      title       TEXT    NOT NULL,
      description TEXT    NOT NULL DEFAULT '',
      created_by  TEXT    NOT NULL DEFAULT '',
      created_at  TEXT    NOT NULL DEFAULT (datetime('now'))
    , slug TEXT DEFAULT NULL, group_id INTEGER REFERENCES groups(id));

DROP TABLE IF EXISTS list_items;
CREATE TABLE list_items (
      id       INTEGER PRIMARY KEY AUTOINCREMENT,
      list_id  INTEGER NOT NULL REFERENCES lists(id)  ON DELETE CASCADE,
      movie_id INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
      position INTEGER NOT NULL DEFAULT 0,
      UNIQUE(list_id, movie_id)
    );

DROP TABLE IF EXISTS list_slug_aliases;
CREATE TABLE list_slug_aliases (
      slug    TEXT    PRIMARY KEY,
      list_id INTEGER NOT NULL REFERENCES lists(id) ON DELETE CASCADE
    );

DROP TABLE IF EXISTS rating_history;
CREATE TABLE rating_history (
      id         INTEGER PRIMARY KEY AUTOINCREMENT,
      movie_id   INTEGER NOT NULL REFERENCES movies(id) ON DELETE CASCADE,
      voter      TEXT    NOT NULL,
      kind       TEXT    NOT NULL DEFAULT 'score',
      score      REAL,
      rank       INTEGER,
      changed_by TEXT    NOT NULL DEFAULT '',
      source     TEXT    NOT NULL DEFAULT 'user',
      changed_at TEXT    NOT NULL DEFAULT (datetime('now'))
    );

COMMIT;
PRAGMA foreign_keys=ON;
